-- Ativo e alvo que apontam para uma categoria nova voltam para a categoria mais
-- próxima do catálogo plano antes de ela sair.
UPDATE asset SET category_id = '01960000-0002-7000-8000-00000000000e'
 WHERE category_id IN (
   '01960000-0002-7000-8000-000000000030',
   '01960000-0002-7000-8000-000000000031',
   '01960000-0002-7000-8000-000000000032',
   '01960000-0002-7000-8000-000000000033'
 );

-- A estratégia que usa alguma delas é descartada inteira: sobraria uma soma que
-- não fecha 100.
DELETE FROM strategy_target
 WHERE portfolio_id IN (
   SELECT portfolio_id FROM strategy_target
    WHERE category_id IN (
      '01960000-0002-7000-8000-000000000020',
      '01960000-0002-7000-8000-000000000021',
      '01960000-0002-7000-8000-000000000022',
      '01960000-0002-7000-8000-000000000023',
      '01960000-0002-7000-8000-000000000024',
      '01960000-0002-7000-8000-000000000030',
      '01960000-0002-7000-8000-000000000031',
      '01960000-0002-7000-8000-000000000032',
      '01960000-0002-7000-8000-000000000033'
    )
 );

UPDATE category SET parent_id = NULL
 WHERE parent_id IN (
   '01960000-0002-7000-8000-000000000020',
   '01960000-0002-7000-8000-000000000021',
   '01960000-0002-7000-8000-000000000022',
   '01960000-0002-7000-8000-000000000023',
   '01960000-0002-7000-8000-000000000024'
 );

DELETE FROM category
 WHERE id IN (
   '01960000-0002-7000-8000-000000000030',
   '01960000-0002-7000-8000-000000000031',
   '01960000-0002-7000-8000-000000000032',
   '01960000-0002-7000-8000-000000000033',
   '01960000-0002-7000-8000-000000000020',
   '01960000-0002-7000-8000-000000000021',
   '01960000-0002-7000-8000-000000000022',
   '01960000-0002-7000-8000-000000000023',
   '01960000-0002-7000-8000-000000000024'
 );
